  LanguageConfig_BonusCardRateText_CN = {
    Text = "\"Benih ibu\"mendapatkan bonus serakah: <NetworkDelayGreen:{s1}>"
  },
  LanguageConfig_BonusCardTipsContent_CN = {
    Text = "1. Penjaga yang memiliki Pembangun tertentu atau Roda takdir (tidak diharuskan untuk diturunkan) dapat memberikan bonus tambahan drop \"Benih ibu\" pada hadiah misi level \"Hasrat kacau\" (termasuk pengulangan), dengan bonus spesifik sebagai berikut: \n· Pembangun \"Thais\": Mencerahkan 0/1/2/3 atau lebih, bonus 20%/30%/40%/50% \n· Roda takdir SSR \"Pemberian Kasih Sayang\": Stack 0/1/2/3 atau lebih, bonus 20%/30%/40%/50% \n· Roda takdir SR \"Perpisahan Panas\": Stack 0/1/2/3 atau lebih, bonus 20%/30%/40%/50% \n2. Bonus \"Kehausan Kuat\" dari Pembangun atau Roda takdir yang berbeda akan dihitung secara kumulatif."
  },
  LanguageConfig_BonusCardTipsTitle_CN = {
    Text = "Penjelasan Bonus Ambisi Kuat"
  },
  LanguageConfig_BonusRuleContent_A24Activity_CN = {
    Text = "1. Penjaga yang memiliki Pembangun tertentu atau Roda takdir (tidak diwajibkan untuk diturunkan) dapat memberikan bonus tambahan drop \"Potongan Memori\" pada hadiah misi level \"Kode Memori\" (termasuk pengulangan), dengan rincian bonus sebagai berikut: \n· Pembangun \"24\": Mencerahkan 0/1/2/3 ke atas, bonus 20%/30%/40%/50% \n· Roda takdir SSR \"Penghisapan Kembali Tubuh Abnormal\": Stack 0/1/2/3 ke atas, bonus 20%/30%/40%/50% \n· Roda takdir SR \"Tetapkan Hati Ikan Cod Perak\": Stack 0/1/2/3 ke atas, bonus 20%/30%/40%/50% \n2. Bonus \"Rasionalitas\" dari Pembangun atau Roda takdir yang berbeda akan dihitung secara kumulatif."
  },
  LanguageConfig_BonusRuleContent_ArachneActivity_CN = {
    Text = "1,Penjaga yang memiliki Awakener atau Roda takdir tertentu (tidak perlu di lapangan) dapat membuat \"Panggung Boneka\" tugas hadiah mendapatkan tambahan jatuh ekstra pada \"Tiket kursi beludru\", dengan rincian tambahan sebagai berikut: \n· Awakener \"Arachne\": Mencerahkan 0/1/2/3 dan lebih, tambahan 20%/30%/40%/50%. \n· Roda takdir SSR \"Jaringan Penenunan Abadi\": Posisi Tumpuk 0/1/2/3 dan lebih, tambahan 20%/30%/40%/50%. \n· Roda takdir SR \"Roda Benang Takdir\": Posisi Tumpuk 0/1/2/3 dan lebih, tambahan 20%/30%/40%/50%. \n2,\"Tambahan aktivitas\" untuk Awakener atau Roda takdir yang berbeda dihitung dengan cara penumpukan."
  },
  LanguageConfig_BonusRuleContent_CarabooActivity_CN = {
    Text = "1、Penjaga yang memiliki Awakener atau Roda takdir tertentu (tidak perlu diturunkan ke lapangan) dapat membuat \"Apel Merah\", \"Apel Emas\", \"Apel Gula\" dalam hadiah misi tingkat \"Harta Umapati\" mendapatkan bonus drop tambahan, detail bonusnya sebagai berikut:\n·Awakener \"Caraboo\": Mencerahkan 0/1/2/3 ke atas, bonus 20%/30%/40%/50%.\n·Roda takdir SSR \"Muslihat Manis\": Posisi Tumpuk 0/1/2/3 ke atas, bonus 20%/30%/40%/50%.\n·Roda takdir SR \"Kebenaran Yang Senyap\": Posisi Tumpuk 0/1/2/3 ke atas, bonus 20%/30%/40%/50%.\n2、\"[Aktivitas]\" dari Awakener atau Roda takdir yang berbeda dihitung dengan cara ditumpuk."
  },
  LanguageConfig_BonusRuleContent_CastorActivity_CN = {
    Text = "1. Penjaga dengan Pembangun atau Roda takdir tertentu (tidak perlu bersaing) dapat memperoleh tambahan droprate pada hadiah misi \"Flyover Sky\" berupa \"Buku Pengetahuan Umum\", \"Buku Matematika\", dan \"Buku Sastra\". Penambahan spesifik adalah sebagai berikut:\n·Pembangun \"Castor\": Mencerahkan0/1/2/3 ke atas, penambahan 20%/30%/40%/50%.\n·SSR Roda takdir \"Kebebasan Tak Tertahankan\": Tingkat 0/1/2/3 ke atas, penambahan 20%/30%/40%/50%.\n·SR Roda takdir \"Ekor Tunggal\": Tingkat 0/1/2/3 ke atas, penambahan 20%/30%/40%/50%.\n2. Penambahan \"Aktivitas\" dari Pembangun atau Roda takdir yang berbeda dihitung dengan cara akumulasi."
  },
  LanguageConfig_BonusRuleContent_ClementineActivity_CN = {
    Text = "1. Penjaga yang memiliki pembangun tertentu atau roda takdir (tidak harus diatur) dapat membuat \"hadiah laporan diagnosis\" dalam tugas level \"Penyembuhan Ketakutan\" mendapatkan tambahan jatuh (termasuk replikasi), dengan tambahan sebagai berikut:\n· Pembangun \"Klementine\": Mencerahkan 0/1/2/3 dan seterusnya, tambahan 20%/30%/40%/50%\n· SSR roda takdir \"Rasa Sakit yang Tersembunyi\": Tumpukan 0/1/2/3 dan seterusnya, tambahan 20%/30%/40%/50%\n· SR roda takdir \"Pendulum Hipnosis\": Tumpukan 0/1/2/3 dan seterusnya, tambahan 20%/30%/40%/50%\n2. \"Tambahan aktivitas\" dari pembangun atau roda takdir yang berbeda dihitung dengan cara ditumpuk."
  },
  LanguageConfig_BonusRuleContent_DaffodilActivity_CN = {
