  },
  LanguageConfig_RailWayLevelAdjustmentTipsContent_CN = {
    Text = "Di dalam \"Kereta Kesukacitaan yang Melaju Kencang\" terdapat mekanisme kompensasi tingkat, dengan aturan sebagai berikut: \n  · Dalam tim penyelidikan, Awakener yang tingkatnya kurang dari 60 akan dikompensasi hingga tingkat 60 dalam tantangan ini. \n  · Dalam tim penyelidikan, Awakener yang tingkat keterampilannya kurang dari 5 akan dikompensasi hingga tingkat 5 dalam tantangan ini. \n  · Dalam tim penyelidikan, Awakener yang memiliki \"Madness Omen\" kurang dari 6 akan dikompensasi hingga tingkat 6 dalam tantangan ini. \n  · Dalam tim penyelidikan, Awakener yang memiliki \"Soulforge Aptitude\" kurang dari 5 akan dikompensasi hingga tingkat 5 dalam tantangan ini. \n  · Jika tingkat Penjaga kurang dari 60, maka dalam tantangan ini akan dikompensasi hingga tingkat 60."
  },
