  LanguageConfig_RailWayStageCrazyNowDesc_CN = {
    Text = [[
Saat ini, ada 3 tahap dalam penyelidikan, setiap tahap terdiri dari 6 pertempuran. 
 Saat ini berada di tahap {s1} - pertempuran ke-{s2}.]]
  },
  LanguageConfig_RailWayStageDifficultyBuffContent1_CN = {
    Text = "<Title:Hadiah Tingkat>\nTahap Pertama: Kalahkan Elite/Pemimpin untuk mendapatkan \"Poin VIP\"×25/75 \nTahap Kedua: Kalahkan Elite/Pemimpin untuk mendapatkan \"Poin VIP\"×50/150 \nTahap Ketiga: Kalahkan Elite/Pemimpin untuk mendapatkan \"Poin VIP\"×75/225 \n<Title:Relik Awal>\nDapatkan Relik\"Kamera Lengkap N Kecil\"pada awal investigasi.\n·<OrangeQuality:Emas Harmony>: Efek peningkatan aritmetika yang diberikan oleh \"Arithmetica Harmony\"maksimal adalah 1 poin, setiap 1% DMG Amplification akan meningkatkan efek Kedalaman Penelitian Spiritual sebesar 1%.\n·<RedQuality:Kelelahan Perjalanan Jauh>: Semua efek pemulihan HP berkurang 50% selama pertempuran."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent2_CN = {
    Text = "<Title:Hadiah Tingkat>\nSemakin tinggi tingkat tantangan, semakin banyak \"Poin VIP\" yang akan didapat. \"Poin VIP\" yang diperoleh setelah menyelesaikan tiga tahap meningkat sebesar 150%\n<Title:Relik Awal>\nDapatkan Relik\"Kamera Tua N Kecil\"pada awal investigasi.\n·<OrangeQuality:Emas Harmoni>: Efek peningkatan aritmetika dari \"Arithmetica Harmony\" maksimum adalah 1 poin, setiap 1%\"DMG Amplification\" akan meningkatkan efek kedalaman penelitian spiritual sebesar 1%.\n·<OrangeQuality:Hadiah Dimensi>: Saat eksplorasi dimulai, secara acak dapatkan 1 Relik Gambar Dimensi, batas tangan maksimum meningkat 1.\n·<RedQuality:Kelelahan Perjalanan Jauh>: Efek pemulihan HP semua berkurang 50% selama pertempuran.\n·<RedQuality:Tanda Stun>: Pada awal pertempuran, semua Awakener kehilangan 50% Aliemus dan Energi-s saat ini."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3V2_CN = {
    Text = "<Title:Tantangan Khusus>\nDalam Kegilaan, setelah menyelesaikan fase ketiga akan ada tantangan tambahan yaitu Pemimpin akhir fase keempat \"Tawil\".\n<Title:Hadiah Tingkat>\nSemakin tinggi kesulitan yang ditantang, akan mendapatkan lebih banyak \"Poin VIP\". \"Poin VIP\" yang diperoleh dari menyelesaikan tiga fase meningkat 400%\nSetelah mengalahkan Pemimpin akhir \"Tawil\", dapat memperoleh tambahan \"Poin VIP\" × 1500.\n<Title:Relic Awal>\nSaat Operasi dimulai mendapatkan Relic \"Kamera Kacau Si Kecil \"N\"\"\n·<OrangeQuality:Harmonisasi Emas>: Efek peningkatan Arithmetica yang dibawa oleh \"Arithmetica Harmony\" maksimal adalah 1 poin, setiap memiliki 1% DMG Amplification maka efek Kedalaman Penelitian Spiritual meningkat 1%.\n·<OrangeQuality:Anugerah Dimensi>: Saat eksplorasi dimulai, secara acak mendapatkan 1 Relic Gambar Dimensi, Maximum Hand Size meningkat 2.\n·<OrangeQuality:Ritual Diberkati>: Hadiah mengalahkan Pemimpin fase pertama dan kedua berubah menjadi pilih 1 dari 3 Relic Diberkati acak.\n·<RedQuality:Kelelahan Perjalanan Jauh>: Dalam pertarungan, semua efek pemulihan HP berkurang 50%.\n·<RedQuality:Tanda Stun>: Saat pertarungan dimulai, Aliemus saat ini dan Keyflare semua Awakener berkurang 50%.\n·<RedQuality:Lorong Malam Abadi>: Saat eksplorasi dimulai, Aliemus Dasar dan batas maksimum Keyflare semua Awakener meningkat 50%"
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3_CN = {
    Text = "<Title:Hadiah Tingkat>\nSemakin tinggi tingkat kesulitan tantangan, semakin banyak \"Poin VIP\" yang akan didapat. Selesaikan tiga tahap untuk meningkatkan \"Poin VIP\" yang didapat sebesar 400%\n<Title:Relik Awal>\nDapatkan relik \"Kamera Kekacauan Kecil \"N\"\" saat eksplorasi dimulai.\n·<OrangeQuality:Emas Harmoni>: Efek peningkatan aritmetika maksimum yang dibawa oleh \"Arithmetica Harmony\" adalah 1 poin, setiap memiliki 1% DMG Amplification akan meningkatkan efek Kedalaman Penelitian Spiritual sebesar 1%.\n·<OrangeQuality:Hadiah Dimensi>: Saat eksplorasi dimulai, secara acak dapatkan 1 Relik Gambar Dimensi, meningkatkan Maximum Hand Size sebesar 2.\n·<OrangeQuality:Ritual Diberkati>: Hadiah untuk mengalahkan pemimpin tahap pertama dan kedua diubah menjadi 1 dari 3 Relik Diberkati secara acak.\n·<RedQuality:Kelelahan Perjalanan Jauh>: Efek pemulihan HP semua berkurang 50% selama pertempuran.\n·<RedQuality:Tanda Stun>: Pada awal pertempuran, semua Awakener kehilangan 50% Aliemus dan Keyflare saat ini.\n·<RedQuality:Lorong Malam Abadi>: Saat eksplorasi dimulai, batas dasar Aliemus dan Keyflare semua Awakener meningkat sebesar 50%."
  },
