  LanguageConfig_Resonance_Group_Desc_1_CN = {
    Text = "Di node [Hadiah Kebaikan], dapat menambahkan 1 kartu [Balasan Polos] ke dalam dek —— Konsumsi Aritmetika 1, berikan 30 Aliemus kepada Pembangun dengan Aliemus terendah, Lelah."
