  },
  LanguageConfig_Resonance_Group_Desc_x1_CN = {
    Text = "Dalam acara resonansi \"Kesadaran yang Belum Hilang\", masukkan satu \"Tangki Otak Cadangan\"ke dalam tumpukan kartu. \"Tangki Otak Cadangan\"dapat menyimpan sementara kartu yang pernah digunakan dan menentukan apakah akan mengambilnya untuk dimasukkan ke tangan berdasarkan situasi yang berbeda."
  },
  LanguageConfig_Resonance_Group_Desc_x2_CN = {
