  LanguageConfig_StoryRole_Unlock_CN = {
    Text = "Garis cerita ini belum terbuka, jadi tidak bisa masuk."
  },
  LanguageConfig_StorylineGuide_0_CN = {
    Text = "Hidup menghadapi kematian."
  },
  LanguageConfig_StorylineGuide_10_CN = {
    Text = "Tentu saja, kekacauan adalah akhir dari segalanya. Tapi selalu ada yang enggan melepaskan perjuangan, bukan?"
  },
  LanguageConfig_StorylineGuide_11_CN = {
    Text = "Jangan lihat langsung ke langit di atas. Jangan lihat langsung ke jurang di dalam hati."
  },
  LanguageConfig_StorylineGuide_12_CN = {
    Text = "Makan adalah satu-satunya kebajikan di dunia ini."
  },
  LanguageConfig_StorylineGuide_13_CN = {
    Text = "Tidak ada jawaban dalam mimpi ilusi yang tak terbatas ini. Mimpi ini, sudah saatnya untuk terbangun."
  },
  LanguageConfig_StorylineGuide_14_CN = {
    Text = "Di atas panggung nasib, peran yang akan kita mainkan, tidak pernah bisa dipilih."
  },
  LanguageConfig_StorylineGuide_15_CN = {
    Text = "Wahai pengembara, melangkahlah perlahan ke dalam malam bersalju. Di Puncak dari Harapan Yang Sirna, saksikanlah Akhir dari Mimpi Agung."
  },
  LanguageConfig_StorylineGuide_16_CN = {
    Text = "Teks sementara"
  },
  LanguageConfig_StorylineGuide_17_CN = {
    Text = "Teks sementara"
  },
  LanguageConfig_StorylineGuide_18_CN = {
    Text = "Teks sementara"
  },
  LanguageConfig_StorylineGuide_19_CN = {
    Text = "Teks sementara"
  },
  LanguageConfig_StorylineGuide_1_CN = {
    Text = "Masuklah ke dalam Kabut Malam yang berbahaya di Londinium, Penjaga. Jalanmu dimulai di sini."
  },
  LanguageConfig_StorylineGuide_20_CN = {
    Text = "Teks sementara"
  },
  LanguageConfig_StorylineGuide_2_CN = {
    Text = "Seniman, orang gila, pertapa, orang yang bodoh… Kota ini adalah galeri milikmu, patung lilin berdiri di tempat pembukaan cerita, menantikan kedatanganmu."
  },
  LanguageConfig_StorylineGuide_3_CN = {
    Text = "Angin dan salju dari Rai membenci pembunuhan, dia menunggu kamu, hanya untuk sebuah transaksi. Dia akan membawakanmu rahasia yang sangat kamu inginkan. Harganya selalu kejam, selalu masuk akal."
  },
  LanguageConfig_StorylineGuide_4_CN = {
    Text = "Ingatlah, berjuanglah demi ingatan, mati demi ingatan. Ingatan adalah kitab Injil kita, nisan kita. Selain ingatan, kita tidak memiliki apa-apa."
  },
  LanguageConfig_StorylineGuide_5_CN = {
    Text = "Sebelum bintang-bintang jatuh, kami berdoa menghadap laut: semoga suara ombak yang tenang melindungi kami masuk ke dalam mimpi, semoga kami kembali ke pelukan tanah air kami, mimpi panjang tak terbangun."
  },
  LanguageConfig_StorylineGuide_6_CN = {
    Text = "Nyanyikanlah——Raja kuno itu telah melihat kembali takhtanya. Wahyu suci akan membawa kerajaan dewa bagi setiap rakyatnya yang setia."
  },
  LanguageConfig_StorylineGuide_7_CN = {
    Text = "Dengarkan, berdoa, panggil, reproduksi, taati cita-cita yang paling mulia dan keinginan yang paling rendah. Demi nama ibu, Dia dapat bertahan di tengah kekacauan dan ketakutan."
  },
  LanguageConfig_StorylineGuide_8_CN = {
    Text = "Lampu abadi telah menyala, cahaya redup itu akan menerangi jalanmu menuju akhir perjalanan."
  },
  LanguageConfig_StorylineGuide_9_CN = {
    Text = "Katakan kepada-Nya, jawabanmu."
  },
  LanguageConfig_StrongerTitle_CN = {
    Text = "Dapatkan bahan melalui\"Selingan\", memperkuat Pembangunmu!"
  },
  LanguageConfig_StrongerWayTitle_CN = {
    Text = "Cara menjadi lebih kuat"
  },
  LanguageConfig_StrongerWay_CN = {
    Text = "·\"Operasi\" 1-2·Normal dibuka:\"Reruntuhan Pelarutan\", dapat memperoleh banyak bahan pengembangan Awakener.\n·\"Operasi\" 3-10·Normal dibuka:\"Keberadaan Transenden\", dapat memperoleh banyak bahan peningkatan keterampilan Awakener.\n·\"Tingkat Investigasi\" dibuka pada level 15:\"Roda takdir kedua\", dapat melengkapi roda takdir kedua untuk mendapatkan kekuatan tempur yang kuat.\n·\"Tingkat Investigasi\" dibuka pada level 25:\"Rekam Tabu\", dapat memperoleh banyak Covenant, meningkatkan kemampuan Awakener."
  },
